namespace TimingAnalyzer.Core;

/// <summary>
/// Which multiple of a section BPM a mapper would write (docs/PHASE1-STATUS.md E36): a multinomial logistic
/// model (<see cref="OctaveModel"/>, generated by tools/octave_train.py) over <see cref="OctaveFeatures"/>, trained on
/// one consensus map per ranked/approved/loved song in the local osu!.db (1 161 sections of 1 073 songs, none of the
/// evaluation sets'). The detected BPM is kept unless another ratio is more probable by <see cref="Margin"/>.
/// </summary>
public static class OctaveSelector
{
    /// <summary>
    /// Song-grouped 5-fold on the training songs: margin 0.2 right on 90.7 % of sections against 77.0 % for keeping the
    /// detected BPM (167 fixed, 8 broken); on the held-out evaluation sections 86.0 % against 79.2 % (28 fixed, 6 broken).
    /// </summary>
    public const double Margin = 0.2;
    /// <summary>
    /// Applied automatically after Auto-time the selector lowers some evaluation set at every margin (0.2: A hold 0.787 →
    /// 0.774 and C tune 0.740 → 0.698; 0.5: C tune → 0.713; 0.8: D tune and E hold), against the user's rule "equal or
    /// better on every set", so the editor only shows it as a hint in Check sections, at this margin: on mappers' own
    /// red lines (every hint a false alarm) 18 of 696 sections of 10 s or more (2.6 %; 0.2 gives 10.9 %), and on
    /// Auto-time's red lines 12 of its 19 hints point at the map's BPM (timing-eval octave-hint, held-out sets).
    /// </summary>
    public const double HintMargin = 0.8;
    public const double MinSectionMs = 10000;

    /// <summary>The ratio to apply to <paramref name="bpm"/> over [start, end), 1 to keep it.</summary>
    public static double Ratio(double[] envelope, double bpm, double startMs, double endMs, double margin = Margin)
    {
        if (endMs - startMs < MinSectionMs) return 1;
        double[] candidates = [0.5, 2.0 / 3, 0.75, 1, 4.0 / 3, 1.5, 2];
        var x = OctaveFeatures.Measure(envelope, bpm, startMs, endMs, candidates);
        var scores = new double[OctaveModel.Ratios.Length];
        for (int c = 0; c < scores.Length; c++)
        {
            double z = OctaveModel.Intercepts[c];
            for (int f = 0; f < x.Length; f++) z += OctaveModel.Weights[c][f] * x[f];
            scores[c] = z;
        }
        double max = scores.Max(), sum = scores.Sum(z => Math.Exp(z - max));
        var p = scores.Select(z => Math.Exp(z - max) / sum).ToArray();
        int keep = Array.FindIndex(OctaveModel.Ratios, r => Math.Abs(r - 1) < 1e-9), best = Array.IndexOf(p, p.Max());
        return best == keep || p[best] - p[keep] < margin ? 1 : OctaveModel.Ratios[best];
    }

    /// <summary>Each section of at least <see cref="MinSectionMs"/> rescaled by <see cref="Ratio"/>; times are kept.</summary>
    public static IReadOnlyList<TimingSection> Apply(double[] envelope, IReadOnlyList<TimingSection> sections, double songEndMs, double margin = Margin)
    {
        var result = new List<TimingSection>();
        for (int i = 0; i < sections.Count; i++)
        {
            double end = i + 1 < sections.Count ? sections[i + 1].TimeMs : songEndMs;
            double r = Ratio(envelope, sections[i].Bpm, sections[i].TimeMs, end, margin);
            result.Add(r == 1 ? sections[i] : sections[i] with { Bpm = sections[i].Bpm * r });
        }
        return result;
    }
}
